class FramingTests(unittest.TestCase):
    def test_all_fragment_boundaries_preserve_payload(self):
        payload = '200 application/json\n\n{"name":"Lumière 🌈"}'.encode()
        wire = len(payload).to_bytes(2, "little") + payload
        for first_size in range(2, len(wire)):
            frame = bridge.FrameAssembler()
            self.assertIsNone(frame.append(wire[:first_size]))
            self.assertEqual(frame.append(wire[first_size:]), payload)

    def test_rejects_zero_short_empty_and_overflow_packets(self):
        for packet in (b"", b"\x01", b"\0\0", b"\x01\0ab"):
            with self.assertRaises(ValueError):
                bridge.FrameAssembler().append(packet)
        frame = bridge.FrameAssembler()
        self.assertIsNone(frame.append(b"\x03\0a"))
        with self.assertRaises(ValueError):
            frame.append(b"bcd")

    def test_response_envelope_rejects_invalid_status_utf8_and_headers(self):
        for payload in (b"200", b"200 \n\n{}", b"99 application/json\n\n{}", b"+200 application/json\n\n{}",
                        b"600 application/json\n\n{}", b"200 app\njson\n\n{}", b"200 application/json\n\n\xff"):
            with self.assertRaises(ValueError):
                bridge.BleApiBridgeClient._parse_response(payload)

    def test_uuid_contract_matches_firmware(self):
        header = pathlib.Path(__file__).resolve().parents[1] / "ble_api_bridge.h"
        values = dict(re.findall(r'constexpr char (\w+_UUID)\[\] = "([^"]+)";', header.read_text()))
        for name in ("SERVICE_UUID", "RX_UUID", "TX_UUID", "LIVE_UUID"):
            self.assertEqual(values[name], getattr(bridge, name))
        self.assertEqual(bridge.TX_UUID, macos_commissioning.TX_UUID)


class CommissioningTests(unittest.IsolatedAsyncioTestCase):
    async def test_adapter_extends_only_tx_probe_and_preserves_other_reads(self):
        class Base:
            async def read_gatt_char(self, characteristic, **kwargs):
                return b"base-read"
        class Adapter(macos_commissioning.ProtectedProbeTimeoutMixin, Base):
            pass
        adapter = Adapter()
        read = AsyncMock(return_value=b"ready")
        adapter._delegate = SimpleNamespace(read_characteristic=read)
        tx = SimpleNamespace(uuid=bridge.TX_UUID, obj=object())
        self.assertEqual(await adapter.read_gatt_char(tx), b"ready")
        read.assert_awaited_once_with(tx.obj, use_cached=False, timeout=90)
        live = SimpleNamespace(uuid=bridge.LIVE_UUID, obj=object())
        self.assertEqual(await adapter.read_gatt_char(live), b"base-read")
        self.assertEqual(read.await_count, 1)

    def test_changed_bleak_version_is_rejected_before_loading_backend(self):
        with patch.object(macos_commissioning, "version", return_value="99.0.0"):
            with self.assertRaisesRegex(RuntimeError, "requires Bleak 3.0.2"):
                macos_commissioning.commissioning_backend()


